module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

reg [1:0] current_state, next_state;

localparam IDLE      = 2'b00;
localparam MOVING_UP = 2'b01;
localparam MOVING_DN = 2'b10;

always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= IDLE;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        IDLE: begin
            if (up_request)
                next_state = MOVING_UP;
            else if (down_request)
                next_state = MOVING_DN;
            else
                next_state = IDLE;
        end
        MOVING_UP: begin
            if (down_request)
                next_state = MOVING_DN;
            else if (!up_request)
                next_state = IDLE;
            else
                next_state = MOVING_UP;
        end
        MOVING_DN: begin
            if (up_request)
                next_state = MOVING_UP;
            else if (!down_request)
                next_state = IDLE;
            else
                next_state = MOVING_DN;
        end
        default: next_state = IDLE;
    endcase
end

assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

reg [1:0] current_state, next_state;

localparam IDLE             = 2'b00;
localparam COIN_INSERTED    = 2'b01;
localparam ITEM_SELECTED    = 2'b10;
localparam DISPENSE         = 2'b11;

always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= IDLE;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        IDLE: begin
            if (coin_inserted)
                next_state = COIN_INSERTED;
            else
                next_state = IDLE;
        end

        COIN_INSERTED: begin
            if (item_selected)
                next_state = DISPENSE;
            else
                next_state = COIN_INSERTED;
        end

        DISPENSE: begin
            next_state = IDLE;
        end

        default: begin
            next_state = IDLE;
        end
    endcase
end

assign state = current_state;

endmodule

