module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [3:0] L0, R0;
    wire [3:0] L1, R1;
    wire [3:0] F;

    assign L0 = data_in[7:4];
    assign R0 = data_in[3:0];

    assign F  = R0 ^ KEY;
    assign L1 = R0;
    assign R1 = L0 ^ F;

    assign data_out = {L1, R1};

endmodule

