module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  reg [1:0] state, next_state;

  localparam A = 2'd0,
             B = 2'd1,
             C = 2'd2,
             D = 2'd3;

  always @(*) begin
    case (state)
      A: next_state = x ? B : A;
      B: next_state = x ? B : C;
      C: next_state = x ? D : A;
      D: next_state = x ? B : C;
      default: next_state = A;
    endcase
  end

  always @(posedge clk or negedge aresetn) begin
    if (!aresetn)
      state <= A;
    else
      state <= next_state;
  end

  always @(*) begin
    case (state)
      A: z = 1'b0;
      B: z = 1'b0;
      C: z = 1'b0;
      D: z = 1'b1;
      default: z = 1'b0;
    endcase
  end

endmodule

