module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam LEFT  = 2'd0;
  localparam RIGHT = 2'd1;
  localparam FALLL = 2'd2;
  localparam FALLR = 2'd3;

  reg [1:0] state, next_state;

  always @(*) begin
    case (state)
      LEFT: begin
        if (!ground)
          next_state = FALLL;
        else if (bump_left)
          next_state = RIGHT;
        else
          next_state = LEFT;
      end

      RIGHT: begin
        if (!ground)
          next_state = FALLR;
        else if (bump_right)
          next_state = LEFT;
        else
          next_state = RIGHT;
      end

      FALLL: begin
        if (ground)
          next_state = LEFT;
        else
          next_state = FALLL;
      end

      FALLR: begin
        if (ground)
          next_state = RIGHT;
        else
          next_state = FALLR;
      end

      default: next_state = LEFT;
    endcase
  end

  always @(posedge clk or posedge areset) begin
    if (areset)
      state <= LEFT;
    else
      state <= next_state;
  end

  assign walk_left  = (state == LEFT);
  assign walk_right = (state == RIGHT);
  assign aaah       = (state == FALLL) || (state == FALLR);

endmodule

