assign raw_sum = A + B + Cin;
assign correction = raw_sum[4] | (raw_sum[3] & (raw_sum[2] | raw_sum[1]));
assign corrected_sum = raw_sum + (correction ? 5'b00110 : 5'b00000);

assign Sum = corrected_sum[3:0];
assign Cout = correction;

endmodule

