module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

always @(posedge clk or negedge rst_n) begin
  if (!rst_n)
    out <= 4'd0;
  else if (valid_count) begin
    if (out == 4'd11)
      out <= 4'd0;
    else
      out <= out + 4'd1;
  end
end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg a_dly;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		a_dly <= 1'b0;
		rise  <= 1'b0;
		down  <= 1'b0;
	end else begin
		rise  <=  a & ~a_dly;
		down  <= ~a &  a_dly;
		a_dly <= a;
	end
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [31:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 32'd0;
            clk_div <= 1'b0;
        end else begin
            if (cnt == (NUM_DIV/2 - 1)) begin
                cnt <= 32'd0;
                clk_div <= ~clk_div;
            end else begin
                cnt <= cnt + 32'd1;
            end
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

reg [2:0] ins_reg;
reg [4:0] ad1_reg;
reg [7:0] ad2_reg;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        ins_reg <= 3'b000;
        ad1_reg <= 5'b00000;
        ad2_reg <= 8'b00000000;
    end else begin
        case (fetch)
            2'b01: begin
                ins_reg <= data[7:5];
                ad1_reg <= data[4:0];
            end
            2'b10: begin
                ad2_reg <= data;
            end
            default: begin
                ins_reg <= ins_reg;
                ad1_reg <= ad1_reg;
                ad2_reg <= ad2_reg;
            end
        endcase
    end
end

assign ins = ins_reg;
assign ad1 = ad1_reg;
assign ad2 = ad2_reg;

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  always @(posedge clk or posedge rst) begin
    if (rst)
      out <= 4'b0001;
    else
      out <= {out[2:0], out[3] ^ out[2]};
  end

endmodule

module right_shifter(clk, q,d);  
    input  clk;  
    input d;  
    output [7:0] q;

    reg [7:0] q;

    always @(posedge clk) begin
        q <= {d, q[7:1]};
    end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] data_a;
reg       toggle_a;
reg       sync_b1, sync_b2, sync_b2_d;

always @(posedge clk_a or negedge arstn) begin
	if (!arstn) begin
		data_a    <= 4'b0000;
		toggle_a  <= 1'b0;
	end else if (data_en) begin
		data_a    <= data_in;
		toggle_a  <= ~toggle_a;
	end
end

always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		sync_b1   <= 1'b0;
		sync_b2   <= 1'b0;
		sync_b2_d <= 1'b0;
		dataout   <= 4'b0000;
	end else begin
		sync_b1   <= toggle_a;
		sync_b2   <= sync_b1;
		sync_b2_d <= sync_b2;
		if (sync_b2 ^ sync_b2_d)
			dataout <= data_a;
	end
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [1:0] state, next_state;

parameter S0 = 2'b00,
          S1 = 2'b01,
          S2 = 2'b10,
          S3 = 2'b11;

always @(posedge CLK or posedge RST) begin
    if (RST)
        state <= S0;
    else
        state <= next_state;
end

always @(*) begin
    case (state)
        S0: begin
            if (IN)
                next_state = S1;
            else
                next_state = S0;
        end
        S1: begin
            if (IN)
                next_state = S1;
            else
                next_state = S2;
        end
        S2: begin
            if (IN)
                next_state = S3;
            else
                next_state = S0;
        end
        S3: begin
            if (IN)
                next_state = S1;
            else
                next_state = S2;
        end
        default: next_state = S0;
    endcase
end

always @(*) begin
    MATCH = (state == S3) && IN;
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shift_reg;
reg [1:0] cnt;
reg valid_r;
reg dout_r;

assign valid_out = valid_r;
assign dout = dout_r;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 4'b0;
        cnt <= 2'b0;
        valid_r <= 1'b0;
        dout_r <= 1'b0;
    end else begin
        if (cnt == 2'b0) begin
            shift_reg <= d;
            dout_r <= d[3];
            valid_r <= 1'b1;
            cnt <= 2'b1;
        end else if (cnt == 2'b1) begin
            dout_r <= shift_reg[2];
            valid_r <= 1'b1;
            cnt <= 2'b10;
        end else if (cnt == 2'b10) begin
            dout_r <= shift_reg[1];
            valid_r <= 1'b1;
            cnt <= 2'b11;
        end else begin
            dout_r <= shift_reg[0];
            valid_r <= 1'b1;
            cnt <= 2'b0;
        end
    end
end

endmodule

