module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

reg [2:0] shift_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        shift_reg <= 3'b000;
    else
        shift_reg <= {shift_reg[1:0], data_in};
end

assign sequence_detected = (shift_reg == 3'b101);

endmodule
